from __future__ import annotations

import argparse
import base64
import struct
from pathlib import Path

# Generated pink Ratanak Media Converter artwork, optimized to a 256px PNG.
# Keeping it embedded makes the Python app and packaged EXE use the same icon
# without depending on a separate runtime asset file.
_ICON_PNG_BASE64 = """"""

def icon_png_bytes() -> bytes:
    return base64.b64decode(_ICON_PNG_BASE64)


def write_icon_files(output_dir: str | Path) -> tuple[Path, Path]:
    """Write the embedded PNG and a Windows ICO containing the 256px PNG."""
    directory = Path(output_dir)
    directory.mkdir(parents=True, exist_ok=True)

    png_bytes = icon_png_bytes()
    png_path = directory / "app_icon.png"
    ico_path = directory / "app_icon.ico"

    png_path.write_bytes(png_bytes)

    # ICO supports PNG-compressed image payloads. A 256x256 entry uses 0 for
    # width/height in the directory entry. Windows scales this for smaller UI
    # surfaces while preserving the original artwork.
    header = struct.pack(
        "<HHHBBBBHHII",
        0,  # reserved
        1,  # image type: icon
        1,  # image count
        0,  # width: 256
        0,  # height: 256
        0,  # palette colors
        0,  # reserved
        1,  # color planes
        32,  # bits per pixel
        len(png_bytes),
        22,  # offset: 6-byte header + 16-byte directory entry
    )
    ico_path.write_bytes(header + png_bytes)
    return png_path, ico_path


def _main() -> int:
    parser = argparse.ArgumentParser(description="Write bundled application icon assets.")
    parser.add_argument("--output-dir", required=True)
    args = parser.parse_args()
    png_path, ico_path = write_icon_files(args.output_dir)
    print(f"Wrote {png_path}")
    print(f"Wrote {ico_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(_main())
